package com.devorld.product; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.List;
public interface ProductRepository extends JpaRepository<Product,Long> { @Query("select p from Product p where (:q is null or lower(p.name) like lower(concat('%',:q,'%'))) and (:category is null or lower(p.category)=lower(:category))") List<Product> search(@Param("q") String q,@Param("category") String category); }
